{
  "story": "Begin with an empty stack and evaluate factorial(3), using factorial(1)=1 and factorial(n)=n×factorial(n−1) for integer n>1. Use Next to follow calls, then compare the stack before and after returns. The newest frame disappears first, while its caller retains its local. Finish with the result and an empty stack.",
  "aha": {
    "stateId": "resume-outer",
    "observation": "A return removes only the newest frame; the waiting caller resumes with its original local and the child's returned value."
  },
  "layout": {
    "preset": "stepper-states",
    "width": 640
  },
  "parts": [
    {
      "id": "recursion-rail",
      "kind": "step-rail",
      "presentation": "Use the approved card shell, with the story and instructions above the experiment. The compact rail carries the process trace. Its active position represents a state, never elapsed time.",
      "bind": {
        "active": "inputs.step",
        "items": "variant.states"
      }
    },
    {
      "id": "call-stack",
      "kind": "fixed-picture",
      "presentation": "Arrange fixed frame regions vertically: Outer at the bottom, Middle above Outer, and Base at the top. Highlighted regions are live frames. Inactive outlines are reference positions, not allocated frames; show their names without their values. The callout identifies the running frame; other live frames are suspended. Local values remain unchanged throughout each frame's lifetime. Assume synchronous execution without inlining or tail-call optimization. Count only factorial frames, excluding runtime and enclosing caller frames. Stack height represents frame count, not memory bytes.",
      "bind": {
        "active": "state.active",
        "regions": "variant.regions",
        "links": "variant.links"
      }
    },
    {
      "id": "running-frame-callout",
      "kind": "active-callout",
      "presentation": "Anchor beside the named frame without covering labels. Identify the active operation without repeating numerical readouts. At empty-stack states, anchor to the Outer reference position.",
      "bind": {
        "target": "state.calloutRegion",
        "text": "state.sentence",
        "reason": "state.why"
      }
    },
    {
      "id": "stack-evidence",
      "kind": "value-readout",
      "presentation": "Place live frames, pushes, and pops together on a shared counter row. Place the latest returned value below, followed by the bound status line. Compute live frames as pushes minus pops from the selected state's event prefix. Pushes and pops count events; depth counts frames; returned values are dimensionless integers. All values are exact, with no rounding. Keep each measurement in this readout only.",
      "bind": {
        "values": "state.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "step",
      "kind": "index",
      "label": "Recursion state",
      "items": "variant.states",
      "presentation": "Detailed parameter-control budget: zero. Navigation budget: one index control and Reset. Provide Previous and Next buttons with those accessible names. Default to the first state, with unit increments, endpoint bounds, and no wrapping. Retain button names when disabled at boundaries. Every state, including the aha state, persists until the learner acts. Provide visible focus and keyboard activation."
    },
    {
      "id": "reset",
      "kind": "reset",
      "label": "Reset",
      "presentation": "Restore the first state and its counter defaults. Fixed inputs never change. Provide visible focus and keyboard activation."
    }
  ],
  "data": {
    "variants": [
      {
        "label": "Factorial: calls and returns",
        "regions": [
          {
            "id": "outer",
            "label": "Outer frame",
            "values": [
              "Saved local n = 3",
              "Continuation: return n × child result"
            ]
          },
          {
            "id": "middle",
            "label": "Middle frame",
            "values": [
              "Saved local n = 2",
              "Continuation: return n × child result"
            ]
          },
          {
            "id": "base",
            "label": "Base frame",
            "values": [
              "Saved local n = 1",
              "Base case: return the saved local"
            ]
          }
        ],
        "links": [],
        "states": [
          {
            "id": "ready",
            "label": "Before the call",
            "short": "Ready",
            "sentence": "The stack is empty before the initial call.",
            "why": "Next enters factorial and creates the Outer frame.",
            "active": [],
            "calloutRegion": "outer",
            "readouts": [
              {
                "id": "depth",
                "label": "Live frames = pushes − pops",
                "value": "0"
              },
              {
                "id": "pushes",
                "label": "Pushes",
                "value": "0"
              },
              {
                "id": "pops",
                "label": "Pops",
                "value": "0"
              },
              {
                "id": "returned",
                "label": "Latest returned value",
                "value": "—"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "No live frames."
              }
            ]
          },
          {
            "id": "push-outer",
            "label": "Push Outer",
            "short": "Call Outer",
            "sentence": "The initial call pushes the Outer frame.",
            "why": "Outer owns its saved local and will wait for a child result before multiplying.",
            "active": [
              "outer"
            ],
            "calloutRegion": "outer",
            "readouts": [
              {
