              },
              {
                "id": "returned",
                "label": "Latest returned value",
                "value": "—"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Outer running at the stack top."
              }
            ]
          },
          {
            "id": "push-middle",
            "label": "Push Middle",
            "short": "Call Middle",
            "sentence": "Outer calls recursively, pushing Middle above itself.",
            "why": "Outer is suspended, not replaced; Middle has a separate saved local.",
            "active": [
              "outer",
              "middle"
