                "label": "Pops",
                "value": "0"
              },
              {
                "id": "returned",
                "label": "Latest returned value",
                "value": "—"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Middle running; Outer suspended."
              }
            ]
          },
          {
            "id": "push-base",
            "label": "Push Base",
            "short": "Call Base",
            "sentence": "Middle calls recursively, pushing Base onto the stack top.",
            "why": "Base reaches the stopping condition without calling another child. Both waiting callers retain their locals and continuations.",
            "active": [
              "outer",
              "middle",
              "base"
            ],
            "calloutRegion": "base",
            "readouts": [
              {
