                "value": "0"
              },
              {
                "id": "returned",
                "label": "Latest returned value",
                "value": "—"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Base running; Middle and Outer suspended."
              }
            ]
          },
          {
            "id": "resume-middle",
            "label": "Pop Base; resume Middle",
            "short": "Return Base",
            "sentence": "Base returns and is popped; Middle resumes at its saved continuation.",
            "why": "Compare the previous state: Base is gone, while Middle's local is unchanged. Middle multiplies that local by the returned value.",
            "active": [
              "outer",
              "middle"
            ],
            "calloutRegion": "middle",
            "readouts": [
              {
