              },
              {
                "id": "pops",
                "label": "Pops",
                "value": "1"
              },
              {
                "id": "returned",
                "label": "Latest returned value",
                "value": "1"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Middle resumed with Base's result; Outer suspended."
              }
            ]
          },
          {
            "id": "resume-outer",
            "label": "Pop Middle; resume Outer",
            "short": "Return Middle",
            "sentence": "Middle returns and is popped; Outer resumes with its original local.",
            "why": "The newest remaining frame leaves first. Outer continues its pending multiplication using Middle's returned value, rather than restarting.",
            "active": [
              "outer"
            ],
            "calloutRegion": "outer",
            "readouts": [
              {
                "id": "depth",
                "label": "Live frames = pushes − pops",
                "value": "1"
              },
              {
                "id": "pushes",
