              },
              {
                "id": "status",
                "label": "Status",
                "value": "Outer resumed with Middle's result; its saved local is unchanged."
              }
            ]
          },
          {
            "id": "finished",
            "label": "Pop Outer; finish",
            "short": "Return Outer",
            "sentence": "Outer returns the final result and is popped.",
            "why": "Every push now has a matching pop. No factorial frame remains.",
            "active": [],
            "calloutRegion": "outer",
            "readouts": [
              {
                "id": "depth",
                "label": "Live frames = pushes − pops",
                "value": "0"
              },
              {
